    shield: '<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>', logout: '<path d="M9 4H4v16h5m5-12 4 4-4 4m-6-4h10"/>', menu: '<path d="M4 6h16M4 12h16M4 18h16"/>',
